  UNION ALL SELECT 'PO-SAM-002','2026-09-05','Shree Electricals','Wiring and fixtures','1 lot','95000','18','112100'
  UNION ALL SELECT 'PO-SAM-003','2026-09-08','Om Interiors','Lobby furniture','1 lot','220000','18','259600'
  UNION ALL SELECT 'PO-SAM-004','2026-09-12','Sai Security Services','Security service','1 month','72000','18','84960'
  UNION ALL SELECT 'PO-SAM-005','2026-09-15','CleanPro Services','Housekeeping service','1 month','55000','18','64900'
  UNION ALL SELECT 'PO-SAM-006','2026-09-18','Aaradhya Plumbing','Plumbing material','1 lot','80000','18','94400'
) AS s
WHERE NOT EXISTS (SELECT 1 FROM purchaseorders p WHERE p.poNumber = s.poNumber);

INSERT INTO vendorbills (vendorName,invoiceNumber,invoiceDate,billAmount,gst,dueDate,status)
SELECT s.* FROM (
  SELECT 'Mahesh Construction' AS vendorName,'MC-SAM-001' AS invoiceNumber,'2026-09-20' AS invoiceDate,'450000' AS billAmount,'81000' AS gst,'2026-10-01' AS dueDate,'Paid' AS status
  UNION ALL SELECT 'Shree Electricals','SE-SAM-014','2026-09-22','125000','22500','2026-10-05','Pending'
  UNION ALL SELECT 'Om Interiors','OI-SAM-009','2026-09-24','275000','49500','2026-10-10','Pending'
  UNION ALL SELECT 'Sai Security Services','SS-SAM-021','2026-09-25','85000','15300','2026-10-12','Pending'
  UNION ALL SELECT 'CleanPro Services','CP-SAM-018','2026-09-26','65000','11700','2026-10-15','Paid'
  UNION ALL SELECT 'Aaradhya Plumbing','AP-SAM-011','2026-09-28','95000','17100','2026-10-18','Pending'
) AS s
WHERE NOT EXISTS (SELECT 1 FROM vendorbills b WHERE b.vendorName = s.vendorName AND b.invoiceNumber = s.invoiceNumber);

INSERT INTO vendorpayments (vendorName,paymentDate,paymentMode,transactionNumber,bank,paidAmount,balanceAmount,status)
SELECT s.* FROM (
  SELECT 'Mahesh Construction' AS vendorName,'2026-09-30' AS paymentDate,'BANK_TRANSFER' AS paymentMode,'TXN-SAM-001' AS transactionNumber,'HDFC Bank' AS bank,'531000' AS paidAmount,'0' AS balanceAmount,'Paid' AS status
  UNION ALL SELECT 'CleanPro Services','2026-09-30','UPI','TXN-SAM-002','HDFC Bank','76700','0','Paid'
  UNION ALL SELECT 'Shree Electricals','2026-10-01','CHEQUE','CHQ-SAM-003','SBI','0','147500','Pending'
  UNION ALL SELECT 'Om Interiors','2026-10-02','BANK_TRANSFER','TXN-SAM-004','ICICI Bank','100000','224500','Partial'
  UNION ALL SELECT 'Sai Security Services','2026-10-03','UPI','TXN-SAM-005','Axis Bank','0','100300','Pending'
  UNION ALL SELECT 'Aaradhya Plumbing','2026-10-04','BANK_TRANSFER','TXN-SAM-006','SBI','50000','62100','Partial'
) AS s
WHERE NOT EXISTS (SELECT 1 FROM vendorpayments p WHERE p.transactionNumber = s.transactionNumber);

INSERT INTO pettycashentries (date,voucherNumber,expenseCategory,description,employeeName,amount,paymentMode,approvedBy)
SELECT s.* FROM (
  SELECT '2026-09-03' AS date,'VC-SAM-001' AS voucherNumber,'Travel' AS expenseCategory,'Property visit travel' AS description,'Amit Sharma' AS employeeName,'2500' AS amount,'Cash' AS paymentMode,'Rajesh Patil' AS approvedBy
  UNION ALL SELECT '2026-09-07','VC-SAM-002','Office Supplies','Stationery purchase','Neha Joshi','1800','UPI','Rajesh Patil'
  UNION ALL SELECT '2026-09-12','VC-SAM-003','Client Meeting','Refreshments for client meeting','Priya Kulkarni','3200','Cash','Rajesh Patil'
  UNION ALL SELECT '2026-09-16','VC-SAM-004','Travel','Local travel for site visit','Rohit Jadhav','1500','UPI','Rajesh Patil'
  UNION ALL SELECT '2026-09-21','VC-SAM-005','Printing','Property brochures printing','Riya Patil','2200','Cash','Rajesh Patil'
  UNION ALL SELECT '2026-09-26','VC-SAM-006','Maintenance','Office equipment maintenance','Kunal Deshpande','4500','Bank Transfer','Rajesh Patil'
) AS s
WHERE NOT EXISTS (SELECT 1 FROM pettycashentries p WHERE p.voucherNumber = s.voucherNumber);

INSERT INTO pettycashapprovals (requestedBy,approvedBy,amount,remarks,status)
SELECT s.* FROM (
  SELECT 'Amit Sharma' AS requestedBy,'Rajesh Patil' AS approvedBy,'2500' AS amount,'Property visit travel' AS remarks,'Approved' AS status
  UNION ALL SELECT 'Neha Joshi','Rajesh Patil','1800','Stationery purchase','Approved'
  UNION ALL SELECT 'Priya Kulkarni','Rajesh Patil','3200','Client meeting refreshments','Approved'
  UNION ALL SELECT 'Rohit Jadhav','Rajesh Patil','1500','Local site visit travel','Approved'
  UNION ALL SELECT 'Riya Patil','Rajesh Patil','2200','Brochure printing','Pending'
  UNION ALL SELECT 'Kunal Deshpande','Rajesh Patil','4500','Equipment maintenance','Pending'
) AS s
WHERE NOT EXISTS (SELECT 1 FROM pettycashapprovals p WHERE p.requestedBy = s.requestedBy AND p.amount = s.amount AND p.remarks = s.remarks);

COMMIT;

